   838  void
   839  exif_data_load_data (ExifData *data, const unsigned char *d_orig,
   840                       unsigned int ds)
   841  {
   842          unsigned int l;
   843          ExifLong offset;
   844          ExifShort n;
   845          const unsigned char *d = d_orig;
   846          unsigned int len, fullds;
   847
   848          if (!data || !data->priv || !d || !ds)
   849                  return;
