   851          exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
   852                    "Parsing %i byte(s) EXIF data...\n", ds);
   853
   854          /*
   855           * It can be that the data starts with the EXIF header. If it does
   856           * not, search the EXIF marker.
   857           */
   858          if (ds < 6) {
   859                  LOG_TOO_SMALL;
   860                  return;
   861          }
   862          if (!memcmp (d, ExifHeader, 6)) {
   863                  exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
   864                            "Found EXIF header at start.");
