   866                  while (ds >= 3) {
   867                          while (ds && (d[0] == 0xff)) {
   868                                  d++;
   869                                  ds--;
   870                          }
   871
   872                          /* JPEG_MARKER_SOI */
   873                          if (ds && d[0] == JPEG_MARKER_SOI) {
   874                                  d++;
   875                                  ds--;
   876                                  continue;
   877                          }
   878
   879                          /* JPEG_MARKER_APP1 */
   880                          if (ds && d[0] == JPEG_MARKER_APP1)
   881                                  break;
   882
   883                          /* Skip irrelevant APP markers. The branch for APP1 must come before this,
   884                             otherwise this code block will cause APP1 to be skipped. This code path
   885                             is only relevant for files that are nonconformant to the EXIF
   886                             specification. For conformant files, the APP1 code path above will be
   887                             taken. */
   888                          if (ds >= 3 && d[0] >= 0xe0 && d[0] <= 0xef) {  /* JPEG_MARKER_APPn */
   889                                  d++;
   890                                  ds--;
   891                                  l = (d[0] << 8) | d[1];
   892                                  if (l > ds)
   893                                          return;
   894                                  d += l;
   895                                  ds -= l;
   896                                  continue;
   897                          }
   898
   899                          /* Unknown marker or data. Give up. */
   900                          exif_log (data->priv->log, EXIF_LOG_CODE_CORRUPT_DATA,
   901                                    "ExifData", _("EXIF marker not found."));
   902                          return;
   903                  }
   904                  if (ds < 3) {
   905                          LOG_TOO_SMALL;
   906                          return;
   907                  }
   908                  d++;
   909                  ds--;
   910                  len = (d[0] << 8) | d[1];
   911                  exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
   912                            "We have to deal with %i byte(s) of EXIF data.",
   913                            len);
   914                  d += 2;
   915                  ds -= 2;
   916          }
   917
   918          /*
   919           * Verify the exif header
   920           * (offset 2, length 6).
   921           */
   922          if (ds < 6) {
   923                  LOG_TOO_SMALL;
   924                  return;
   925          }
   926          if (memcmp (d, ExifHeader, 6)) {
   927                  exif_log (data->priv->log, EXIF_LOG_CODE_CORRUPT_DATA,
   928                            "ExifData", _("EXIF header not found."));
   929                  return;
   930          }
   931
   932          exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
   933                    "Found EXIF header.");
