   939          /* The JPEG APP1 section can be no longer than 64 KiB (including a
   940             16-bit length), so cap the data length to protect against overflow
   941             in future offset calculations */
   942          fullds = ds;
   943          if (ds > 0xfffe)
   944                  ds = 0xfffe;
