   946          /* Byte order (offset 6, length 2) */
   947          if (!memcmp (d + 6, "II", 2))
   948                  data->priv->order = EXIF_BYTE_ORDER_INTEL;
   949          else if (!memcmp (d + 6, "MM", 2))
   950                  data->priv->order = EXIF_BYTE_ORDER_MOTOROLA;
   951          else {
   952                  exif_log (data->priv->log, EXIF_LOG_CODE_CORRUPT_DATA,
   953                            "ExifData", _("Unknown encoding."));
   954                  return;
   955          }
   956
   957          /* Fixed value */
   958          if (exif_get_short (d + 8, data->priv->order) != 0x002a)
   959                  return;
   960
   961          /* IFD 0 offset */
   962          offset = exif_get_long (d + 10, data->priv->order);
   963          exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
   964                    "IFD 0 at %i.", (int) offset);
   965
   966          /* ds is restricted to 16 bit above, so offset is restricted too, and offset+8 should not overflow. */
   967          if (offset > ds || offset + 6 + 2 > ds)
   968                  return;
   969
   970          /* Parse the actual exif data (usually offset 14 from start) */
   971          exif_data_load_data_content (data, EXIF_IFD_0, d + 6, ds - 6, offset, 0);
   972
   973          /* IFD 1 offset */
   974          n = exif_get_short (d + 6 + offset, data->priv->order);
   975          /* offset < 2<<16, n is 16 bit at most, so this op will not overflow */
   976          if (offset + 6 + 2 + 12 * n + 4 > ds)
   977                  return;
   978
   979          offset = exif_get_long (d + 6 + offset + 2 + 12 * n, data->priv->order);
   980          if (offset) {
   981                  exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
   982                            "IFD 1 at %i.", (int) offset);
   983
   984                  /* Sanity check. ds is ensured to be above 6 above, offset is 16bit */
   985                  if (offset > ds - 6) {
   986                          exif_log (data->priv->log, EXIF_LOG_CODE_CORRUPT_DATA,
   987                                    "ExifData", "Bogus offset of IFD1.");
   988                  } else {
   989                     exif_data_load_data_content (data, EXIF_IFD_1, d + 6, ds - 6, offset, 0);
   990                  }
   991          }
   992
   993          /*
   994           * If we got an EXIF_TAG_MAKER_NOTE, try to interpret it. Some
   995           * cameras use pointers in the maker note tag that point to the
   996           * space between IFDs. Here is the only place where we have access
   997           * to that data.
   998           */
   999          interpret_maker_note(data, d, fullds);
  1000
  1001          /* Fixup tags if requested */
  1002          if (data->priv->options & EXIF_DATA_OPTION_FOLLOW_SPECIFICATION)
  1003                  exif_data_fix (data);
  1004  }
